/// <reference types="cypress" />
/**
 * Porch lane-local helpers (Epic #2821 — "Open Porch in the browser shell").
 * NOT steward-owned — this file is single-owner to the porch tranche, mirroring
 * range/_helpers.ts and kite/_helpers.ts's own doc comments. Shared foundation
 * (cy.login, cy.origin, personas, selectors) lives under support/ and stays
 * frozen; this module re-uses the range lane's exercise/membership seeding
 * surface directly rather than duplicating it, since Porch is a platform
 * SURFACE inside a Range exercise, not a separate product with its own
 * exercise/membership model.
 *
 * The one seam range/_helpers.ts has no equivalent for is platform_visibility
 * (#1478's per-exercise participant denylist, see
 * frontends/range-mfe/src/lib/platformVisibility.ts) — `setPlatformVisibility`
 * below fills that in with a direct PATCH, mirroring what
 * useSetPlatformVisibility.ts / PlatformsCard.tsx drive from the UI.
 */
import type { PersonaCreds } from "../../support/commands";
import {
  porchAccountLogInItem,
  porchAccountLogOutItem,
  porchAccountMenuButton,
  porchLoginDialog,
} from "../../support/selectors";
import {
  assignExerciseRole,
  bffPost,
  createActiveExercise,
  createCharacter,
  createFaction,
  uniq,
  visitRange,
} from "../range/_helpers";

export { assignExerciseRole, createActiveExercise, uniq, visitRange };

interface Envelope<T> {
  data?: T;
}

/** Unwrap the range-bff `{ data: ... }` envelope, tolerating a bare payload. */
function unwrap<T>(body: unknown): T {
  if (body && typeof body === "object" && "data" in body) {
    const env = body as Envelope<T>;
    if (env.data !== undefined) return env.data;
  }
  return body as T;
}

/**
 * The shared seeding chain both public seeders below are built on: log in as
 * P6 (creator/instructor), mint P7, create an ACTIVE exercise, enroll P7 as
 * STUDENT, run `whileInstructor` against that exercise while STILL on the P6
 * session, then switch to P7 and yield whatever `whileInstructor` produced.
 *
 * The P6-before-P7 ordering is the whole reason this is one helper: anything
 * needing RANGE_ADMIN on the exercise (credential minting) has to happen
 * before the session switches, and expressing that as a callback slot makes
 * it impossible for a caller to get the order wrong.
 */
function seedExerciseAsP7<T>(
  namePrefix: string,
  whileInstructor: (exerciseId: string) => Cypress.Chainable<T>,
): Cypress.Chainable<T> {
  cy.login("P6");
  return cy
    .task<PersonaCreds>("mintPersona", { persona: "P7" })
    .then((p7): Cypress.Chainable<T> =>
      createActiveExercise(uniq(namePrefix)).then((exerciseId): Cypress.Chainable<T> =>
        assignExerciseRole(exerciseId, p7.kcUserId, "student").then(
          (): Cypress.Chainable<T> =>
            whileInstructor(exerciseId).then(
              (result): Cypress.Chainable<T> =>
                cy.login("P7").then((): Cypress.Chainable<T> => cy.wrap<T>(result)),
            ),
        ),
      ),
    );
}

/**
 * Seed an active exercise, enroll P7 as STUDENT (the exercise-membership
 * "Participant" role), then switch the active cy.session to P7. Yields the
 * exercise id. Mirrors range/participant-env-shell.cy.ts's
 * seedEnvExerciseAsP7, generalized to a bare exercise id (this lane's specs
 * only need the id, not the exercise name).
 */
export function seedEnvExerciseAsP7(
  namePrefix = "Porch Env",
): Cypress.Chainable<string> {
  return seedExerciseAsP7(namePrefix, (exerciseId) => cy.wrap<string>(exerciseId));
}

/**
 * PATCH the exercise's `platform_visibility` denylist directly (#1478),
 * riding the shell proxy on whatever persona is CURRENTLY logged in — call
 * this while logged in as the exercise creator/instructor, since a
 * participant session has no write access to exercise settings.
 *
 * range-bff's PlatformVisibility field is a POINTER TO A MAP: a partial
 * `{ porch: false }` payload is a valid, deliberate partial denylist — every
 * OTHER key is simply absent, which `parsePlatformVisibility` /
 * `isPlatformEnabled` (platformVisibility.ts) both read as "enabled" by
 * default. This mirrors exactly what a single PlatformsCard toggle click
 * persists server-side EXCEPT that the real UI always sends the full
 * five-key map (useSetPlatformVisibility.ts) — sending only the key under
 * test is simpler here and observably equivalent, since an absent key and an
 * explicit `true` are the same enabled state.
 */
export function setPlatformVisibility(
  exerciseId: string,
  visibility: Readonly<Record<string, boolean>>,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "PATCH",
    url: `/api/v1/range/exercises/${exerciseId}`,
    body: { platform_visibility: visibility },
    headers: { "Content-Type": "application/json", Accept: "application/json" },
  });
}

// ---------------------------------------------------------------------------
// Porch acting identity (#2869) — a Porch login/logout is a DIFFERENT trust
// zone from the exercise-membership seam above: it authenticates a
// CHARACTER against range-bff's ParticipantCredentialService (the exact
// same service Kite/Commons verify against, per
// services/range-bff/internal/handlers/porch.go's Login doc comment), never
// the shell's own Keycloak session. There is no cookie-planting shortcut
// here (unlike cy.loginParticipantX/Commons) — the whole point of this
// slice's UI is that the credential is typed into PorchLoginModal in place,
// so these helpers drive the real form rather than short-circuiting it.
// ---------------------------------------------------------------------------

export interface PorchCredential {
  readonly characterId: string;
  readonly handle: string;
  readonly password: string;
  readonly displayName: string;
}

/**
 * Provision a human-playable (non-synthetic) character under `exerciseId`
 * and mint a Porch-loginnable credential for it via the SAME
 * `credentials:generate` route Kite/Commons use — range-bff's Porch Login
 * verifies against the identical ParticipantCredentialService, so one
 * credential authenticates any of the three surfaces. Call while logged in
 * as the exercise instructor/RANGE_ADMIN (P6 by default) — credential
 * minting requires that role on the exercise, mirroring
 * kite/_helpers.ts's createLoginnableCharacter.
 */
export function seedPorchCredential(
  exerciseId: string,
  displayName = "Jordan Ashworth",
): Cypress.Chainable<PorchCredential> {
  return createFaction(exerciseId, { name: uniq("Porch Faction") }).then((factionId) =>
    createCharacter(exerciseId, {
      faction_id: factionId,
      username: uniq("porchparticipant").toLowerCase().replace(/[^a-z0-9]/g, ""),
      display_name: displayName,
      is_synthetic: false,
    }).then((characterId) =>
      bffPost(`/api/v1/kite/exercises/${exerciseId}/credentials:generate`, {
        character_id: characterId,
      }).then((resp) => {
        const inner = unwrap<{ handle?: string; password?: string }>(resp.body);
        expect(inner.handle, "generated porch credential handle").to.be.a("string");
        expect(inner.password, "generated porch credential password").to.be.a("string");
        return {
          characterId,
          handle: inner.handle as string,
          password: inner.password as string,
          displayName,
        };
      }),
    ),
  );
}

/**
 * Open the Porch account menu and click "Log in" — asserts the login modal
 * (`PorchLoginModal`, "Log in to Porch") opens IN PLACE, never a navigation
 * (#2869 journey 3). Leaves the modal open for the caller to fill in.
 */
export function openPorchLoginModal(): void {
  porchAccountMenuButton().click();
  porchAccountLogInItem().click();
  porchLoginDialog().should("be.visible");
}

/**
 * Fill the open `PorchLoginModal`'s Handle/Password fields and submit.
 * Does not assert the outcome — callers assert either the modal closing
 * (success) or the inline error appearing (failure).
 */
export function submitPorchLogin(handle: string, password: string): void {
  porchLoginDialog().within(() => {
    cy.findByLabelText("Handle").clear().type(handle);
    cy.findByLabelText("Password").type(password, { log: false });
    cy.findByRole("button", { name: "Log in" }).click();
  });
}

/**
 * Full UI-driven Porch login: open the modal, fill the credential, submit,
 * and wait for the modal to close (success path only — see
 * `submitPorchLogin` for driving the invalid-credential path directly).
 */
export function loginToPorch(handle: string, password: string): void {
  openPorchLoginModal();
  submitPorchLogin(handle, password);
  porchLoginDialog().should("not.exist");
}

/** Open the Porch account menu and click "Log out" (#2869 journey 5). */
export function logOutOfPorch(): void {
  porchAccountMenuButton().click();
  porchAccountLogOutItem().click();
}

export interface PorchSessionFixture {
  readonly exerciseId: string;
  readonly credential: PorchCredential;
}

/**
 * `seedEnvExerciseAsP7` PLUS a Porch-loginnable credential on the same
 * exercise — for specs that need to actually log a character into Porch
 * (login/logout/composer journeys), not just read the anonymous feed.
 *
 * Ends on the P7 session, in the env shell's own exercise route — exactly
 * `seedEnvExerciseAsP7`'s contract — so a caller does not have to know about
 * the P6 detour in between.
 */
export function seedPorchSessionFixture(
  namePrefix = "Porch Login",
  displayName = "Jordan Ashworth",
): Cypress.Chainable<PorchSessionFixture> {
  return seedExerciseAsP7(namePrefix, (exerciseId) =>
    seedPorchCredential(exerciseId, displayName).then(
      (credential): PorchSessionFixture => ({ exerciseId, credential }),
    ),
  );
}


--- frontends/cypress/cypress/e2e/porch/porch-composer.cy.ts (134 lines) ---
/**
 * Porch composer build-out (issue #2944 — "Build the real Porch composer").
 *
 * `ComposerStub` is gone: the inline feed-column trigger opens a real Radix
 * dialog with a growing textarea, a Public/Friends/Only-me audience
 * selector defaulting to Public, and an attachment tray whose four tabs
 * (Photo/Video/Poll/Feeling) are ALL currently unavailable — #2822 / #2825 /
 * #2826 / #2823 flip them on one at a time, none of which have landed yet.
 *
 * `onSubmit` is not wired in this batch (no backend write RPC exists for
 * Porch posts yet), so the Post button sits in its inert `aria-disabled`
 * "unavailable" state per the component's own state machine
 * (`PorchComposerModal.tsx`) — this spec asserts exactly that, and
 * deliberately does NOT attempt to submit a post or assert one was created.
 *
 * Every "unavailable" assertion below checks `aria-disabled`, never
 * `:disabled` — per this package's a11y convention (and this ticket's own
 * instructions), an inert control here stays a real, focusable element with
 * `aria-disabled="true"` + a paired `aria-describedby` hint, never native
 * `disabled` (which would drop it from the tab order).
 *
 * The composer trigger only exists once a Porch acting identity is present
 * (#2869's "no acting profile -> no compose entry point"), so every test
 * here logs a character in first via `_helpers.ts`'s `seedPorchSessionFixture`
 * / `loginToPorch` — the same real, UI-driven login porch-session.cy.ts
 * uses, not a shortcut.
 */
import { loginToPorch, seedPorchSessionFixture, visitRange } from "./_helpers";
import {
  porchComposerDialog,
  porchComposerTrigger,
  porchToolbarButton,
} from "../../support/selectors";

function openComposer(): void {
  porchComposerTrigger().click();
  porchComposerDialog().should("be.visible");
}

describe("porch: composer — trigger, modal, audience, attachment tray", () => {
  beforeEach(() => {
    seedPorchSessionFixture("Porch Composer").then(({ exerciseId, credential }) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();
      loginToPorch(credential.handle, credential.password);
    });
  });

  it("the inline trigger opens the composer modal, and Escape closes it exactly once and restores focus to the trigger", () => {
    openComposer();

    porchComposerDialog().within(() => {
      cy.findByRole("textbox", { name: "Post text" }).should("be.visible");
    });

    cy.get("body").type("{esc}");
    porchComposerDialog().should("not.exist");
    porchComposerTrigger().should("have.focus");
  });

  it("the audience selector defaults to Public and every option is a real, labelled radio", () => {
    openComposer();

    porchComposerDialog().within(() => {
      cy.findByRole("radio", { name: "Public" }).should(
        "have.attr",
        "aria-checked",
        "true",
      );
      cy.findByRole("radio", { name: "Friends" }).should(
        "have.attr",
        "aria-checked",
        "false",
      );
      cy.findByRole("radio", { name: "Only me" }).should(
        "have.attr",
        "aria-checked",
        "false",
      );

      cy.findByRole("radio", { name: "Friends" }).click();
      cy.findByRole("radio", { name: "Friends" }).should(
        "have.attr",
        "aria-checked",
        "true",
      );
      cy.findByRole("radio", { name: "Public" }).should(
        "have.attr",
        "aria-checked",
        "false",
      );
    });
  });

  it("every attachment tab is unavailable via aria-disabled, never native disabled, each naming what's missing", () => {
    openComposer();

    porchComposerDialog().within(() => {
      for (const label of ["Photo", "Video", "Poll", "Feeling"]) {
        cy.findByRole("button", { name: label })
          .as("tab")
          .should("have.attr", "aria-disabled", "true")
          .and("not.be.disabled");

        cy.get("@tab")
          .invoke("attr", "aria-describedby")
          .then((describedBy) => {
            expect(describedBy, `${label} tab has an aria-describedby hint`).to.be.a(
              "string",
            );
            cy.get(`[id="${describedBy}"]`).should(
              "contain.text",
              `${label} isn't available yet.`,
            );
          });
      }
    });
  });

  it("the Post button sits inert (aria-disabled) since onSubmit isn't wired in this batch, even with text typed", () => {
    openComposer();

    porchComposerDialog().within(() => {
      cy.findByRole("textbox", { name: "Post text" }).type(
        "Looking forward to the community garden cleanup this weekend.",
      );

      cy.findByRole("button", { name: "Post" })
        .should("have.attr", "aria-disabled", "true")
        .and("not.be.disabled");
    });
  });
});


--- frontends/cypress/cypress/e2e/porch/porch-platform.cy.ts (237 lines) ---
/**
 * Porch platform surface in the Range browser shell (Epic #2821 — "Open
 * Porch in the browser shell").
 *
 * Porch is the newest LIVE simulated platform (an original Facebook analogue,
 * epic #1872's rebrand) inside the Range participant environment shell:
 * `platforms.ts` now carries `porch: { route: "porch", built: true }`, so its
 * toolbar launcher (`PorchPlatformButton`) is a real, focusable `<button>` —
 * not the disabled "Soon" panel every other still-unbuilt platform (Frame,
 * Courier) renders via `UnbuiltPlatform`. Clicking it, or typing `porch.range`
 * into the omnibox, mounts the FEDERATED `porch/PorchApp` remote in-shell via
 * `PlatformHost` (mirrors how Commons is mounted, see BrowserShell.tsx /
 * PlatformHost.tsx doc comments).
 *
 * There is NO real Porch API yet (#2869 tracks it) — every
 * `porchStubHooks.ts` hook is still hard-coded to `{ state: "empty" }`, so
 * Friends, the routed Groups page, and Saved still render their localized
 * EMPTY state (unchanged, and exercised below). Feed (#2941) and the left/
 * right rail cards (#2946/#2947) bypass that hook entirely, though, and
 * render from populated `PORCH_*_FEW`/`PORCH_POST_FIXTURES` fixtures
 * instead — this spec's own chrome-level assertions (a real search
 * landmark now exists; the logged-out composer slot shows a Log-in prompt)
 * reflect that. That split is the correct, current behavior, not a bug this
 * spec should flag.
 *
 * Journey covered (mirrors range/participant-env-shell.cy.ts's shape, the
 * closest analogue for the env-shell chrome itself, and kite/_helpers.ts's
 * for a federated in-shell surface):
 *   1. A participant lands in the simulated browser and the Porch tile is a
 *      real, focusable button.
 *   2. Clicking it mounts the Porch surface; the omnibox reads porch.range.
 *   3. Typing porch.range from another surface (a search results page)
 *      navigates to Porch.
 *   4. An in-surface navigation (Feed -> Friends) writes its path back to the
 *      address bar, and pasting that URL back reproduces the same view.
 *   5. Back/Forward move between Porch and the previous surface with the
 *      path preserved.
 *   6. Disabling Porch for the exercise hides the participant's entry point;
 *      the instructor's own Setup -> Platforms control for it stays
 *      reachable (see the final `it` for exactly what this does and does not
 *      prove — flagged there and in the authoring report).
 *
 * Actors: P6 (creator -> instructor, matching every other range wizard/admin
 * spec) and P7 (exercise STUDENT -> participant), assigned per-spec via
 * assignExerciseRole — personas only grant the ORG layer.
 */
import {
  seedEnvExerciseAsP7,
  setPlatformVisibility,
  visitRange,
} from "./_helpers";

/** The toolbar omnibox — persistent across every content-slot swap. */
function omnibox(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("textbox", { name: "Search or type a web address" });
}

/** Commit a URL/query into the toolbar omnibox (replacing whatever is there). */
function navigateOmnibox(value: string): void {
  omnibox().clear().type(`${value}{enter}`);
}

/** The toolbar's Porch launcher button (aria-label m.range_platform_porch(), "Porch"). */
function porchButton(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: "Porch" });
}

/**
 * The mounted PorchApp's left-rail nav (`PorchNav`, aria-label "App
 * sections"). PorchTopTabs duplicates the first three destinations
 * (Feed/Friends/Groups) in its own "Main sections" nav at desktop widths, so
 * every in-surface nav-link click below is scoped through this to avoid an
 * ambiguous multi-match.
 */
function porchNav(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("navigation", { name: "App sections" });
}

describe("porch: platform surface in the browser shell", () => {
  it("a participant lands in the simulated browser on the search home, and the Porch toolbar button is real and focusable", () => {
    seedEnvExerciseAsP7().then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);

      // Landed in the simulated browser (env shell chrome), on the search home.
      cy.findByRole("search").should("be.visible");
      omnibox().should("be.visible");

      // The Porch entry point is a real, enabled, focusable <button>.
      // NOTE: #2821's wording talks about a launcher TILE, but the launcher
      // grid (PlatformLauncher) is not mounted in the app — SearchHome.tsx
      // records that it "was removed per user cleanup; platforms are
      // reachable via the omnibox". The live affordances are this toolbar
      // button and the omnibox, so that is what this lane exercises.
      porchButton()
        .should("be.visible")
        .and("not.be.disabled")
        .focus()
        .should("have.focus");
    });
  });

  it("clicking Porch mounts the surface and the omnibox reads porch.range", () => {
    seedEnvExerciseAsP7().then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);

      porchButton().click();

      // Search home is gone; the federated PorchApp is mounted (its topbar
      // brand wordmark link). PorchSearch (#2945) replaced the old,
      // role-less `PorchSearchStub` with a real `<form role="search">`,
      // mounted unconditionally in the topbar — so a search landmark
      // genuinely exists here too now, just Porch's own, not the env
      // shell's. And with no `porch_session` seeded (seedEnvExerciseAsP7
      // mints none), the composer slot renders the logged-out Log-in
      // prompt (`PorchComposerLoginPrompt`), not the composer trigger — see
      // porch-session.cy.ts's identical assertion for this same seeding
      // path.
      cy.findByRole("search").should("be.visible");
      cy.findByRole("link", { name: "Porch" }).should("be.visible");
      cy.findByRole("button", { name: "Log in" }).should("be.visible");

      omnibox().should("have.value", "https://porch.range/");
    });
  });

  it("typing porch.range from another surface (a search results page) navigates to Porch", () => {
    seedEnvExerciseAsP7().then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);

      // Land on a DIFFERENT surface first — the SERP (mirrors
      // participant-env-shell.cy.ts's search->SERP transition).
      navigateOmnibox("summit");
      cy.findByRole("tab", { name: "Websites" }).should("be.visible");

      // From there, typing porch.range navigates to Porch.
      navigateOmnibox("porch.range");
      cy.findByRole("link", { name: "Porch" }).should("be.visible");
      omnibox().should("have.value", "https://porch.range/");
    });
  });

  it("an in-surface navigation writes its path back to the address bar, and pasting that URL back reproduces the same view", () => {
    seedEnvExerciseAsP7().then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchButton().click();

      // In-surface nav: Feed -> Friends, via the left-rail nav.
      porchNav().findByRole("link", { name: "Friends" }).click();
      cy.findByText("No friends yet").should("be.visible");
      omnibox().should("have.value", "https://porch.range/friends");

      // Navigate away (Home restores the search home), then paste the
      // captured URL back into the omnibox — it must reproduce the SAME view.
      cy.findByRole("button", { name: "Home" }).click();
      cy.findByRole("search").should("be.visible");

      navigateOmnibox("https://porch.range/friends");
      cy.findByText("No friends yet").should("be.visible");
      omnibox().should("have.value", "https://porch.range/friends");
    });
  });

  it("Back/Forward move between Porch and the previous surface with the path preserved", () => {
    seedEnvExerciseAsP7().then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);

      const backBtn = () => cy.findByRole("button", { name: "Back" });
      const forwardBtn = () => cy.findByRole("button", { name: "Forward" });
      backBtn().should("be.disabled");

      // Navigate straight to a Porch sub-path from the search home.
      navigateOmnibox("porch.range/friends");
      cy.findByText("No friends yet").should("be.visible");
      omnibox().should("have.value", "https://porch.range/friends");
      backBtn().should("be.enabled");

      // Back restores the previous surface (the search home).
      backBtn().click();
      cy.findByRole("search").should("be.visible");
      backBtn().should("be.disabled");
      forwardBtn().should("be.enabled");

      // Forward returns to Porch with the path preserved.
      forwardBtn().click();
      cy.findByText("No friends yet").should("be.visible");
      omnibox().should("have.value", "https://porch.range/friends");
    });
  });

  /**
   * #1478's per-exercise participant denylist, applied to Porch.
   *
   * CONFIDENCE NOTE (see the authoring report): PlatformHost.tsx's own
   * "disabled platform" panel (`m.range_platform_disabled_title/body`, "This
   * platform is unavailable" / "Your instructor has turned off this platform
   * for this exercise.") is explicit defense-in-depth for an entry that
   * reaches PlatformHost DESPITE being disallowed — the real gate is
   * BrowserShell's `navigateTo` chokepoint (which silently substitutes
   * HOME_ENTRY for a disallowed entry) plus `sanitizeNavState` (which strips
   * a disallowed entry from persisted history before the shell's first
   * paint). Both run BEFORE the panel's own check, and neither is
   * role-scoped in the current code (EnvShellRoute resolves the SAME
   * `platform_visibility` document for every caller regardless of
   * instructor/participant role) — so no normal UI interaction this spec
   * could drive actually reaches that literal panel, for EITHER role. What
   * IS reliably, role-differentiated observable is: the participant's
   * toolbar entry point disappears entirely (`PorchPlatformButton`'s
   * `isEnabled` cosmetic hide), while the instructor's Setup -> Platforms
   * control for Porch stays a live, operable switch (i.e. disabling Porch for
   * participants does not lock the instructor out of the control itself).
   * That is what this test asserts.
   */
  it("disabling Porch for the exercise hides the participant's entry point; the instructor's own toggle for it stays reachable", () => {
    seedEnvExerciseAsP7("Porch Disabled").then((exerciseId) => {
      // P7 is now the active session (seedEnvExerciseAsP7's last step) —
      // switch back to the creator/instructor P6 to persist the denylist.
      cy.login("P6");
      setPlatformVisibility(exerciseId, { porch: false });

      // Participant: no Porch entry point at all.
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);
      cy.findByRole("search").should("be.visible");
      porchButton().should("not.exist");

      // Instructor: Setup -> Platforms still exposes a live, operable Porch
      // switch, reflecting the current off state.
      cy.login("P6");
      visitRange(`/range/exercises/${exerciseId}/admin/settings?tab=platforms`);
      cy.findByRole("switch", { name: "Show Porch to participants" })
