/**
 * Porch acting identity (Epic #268, issue #2869 — "Porch backend
 * foundation: schema, reads and acting identity").
 *
 * Porch has TWO trust zones on one surface, and this spec is the one that
 * proves the boundary between them from the outside:
 *
 *   - READ rides the shell's own Keycloak session — a participant with NO
 *     `porch_session` opens Porch and sees the feed, no login step, no
 *     redirect, no blocking login route.
 *   - ACT AS A CHARACTER (post/react/comment, later slices) requires an
 *     opaque `porch_session` cookie, acquired by logging a synthetic
 *     profile's credential into `PorchLoginModal` — a dialog opened IN
 *     PLACE from the topbar account menu, never a navigation.
 *
 * Journeys covered (#2869's acceptance criteria, numbered per the issue):
 *   1. No `porch_session` -> the feed renders (from #2941's populated
 *      fixture — FeedRoute is intentionally not login-state-aware yet),
 *      no login step.
 *   2. No acting profile -> the chrome shows a Log-in affordance and no
 *      compose entry point.
 *   3. Clicking it opens the login modal in place (no navigation).
 *   4. A valid credential closes the modal onto the same feed, with the
 *      character's identity in the account menu and the composer unlocked.
 *   5. Logging out returns to the logged-out-but-readable state; the
 *      shell's own session is unaffected.
 *   6. An invalid credential produces a localized, non-enumerating error
 *      and leaves the modal open.
 *
 * Journey 7 (Porch disabled for the exercise -> the participant read is
 * refused and the localized unavailable panel shows) is deliberately NOT
 * added here: porch-platform.cy.ts's own "disabling Porch" test already
 * covers the only UI-reachable half of that acceptance criterion — the
 * participant's toolbar entry point disappearing entirely — and its
 * header comment documents, with a confidence note, that BrowserShell's
 * `navigateTo` chokepoint silently substitutes the home entry for a
 * disallowed destination BEFORE PlatformHost's own disabled-platform panel
 * ever gets a chance to render, for either role. No normal UI interaction
 * this spec could drive reaches that literal panel either, so duplicating
 * that test here would only re-assert the same toolbar-hiding behavior
 * under a different file name.
 *
 * Credential seam: unlike the standalone Kite/Commons participant clones,
 * Porch has no cookie-planting `cy.loginParticipantX`-style shortcut here —
 * the whole point of this UI is that the credential is typed into
 * `PorchLoginModal`, so `_helpers.ts`'s `seedPorchSessionFixture` mints a
 * real credential via the SAME `credentials:generate` route Kite/Commons
 * use, and every login below drives the real form.
 *
 * Actors: P6 (creator/instructor, only for seeding) and P7 (exercise
 * STUDENT -> the acting participant), matching porch-platform.cy.ts.
 */
import {
  loginToPorch,
  logOutOfPorch,
  openPorchLoginModal,
  seedPorchSessionFixture,
  submitPorchLogin,
  visitRange,
} from "./_helpers";
import {
  porchAccountLogInItem,
  porchAccountLogOutItem,
  porchAccountMenu,
  porchAccountMenuButton,
  porchComposerTrigger,
  porchLoginDialog,
  porchToolbarButton,
  userMenuButton,
} from "../../support/selectors";

describe("porch: acting identity — login, logout, invalid credentials", () => {
  it("a participant with no porch_session sees the feed, with a log-in affordance and no compose entry point", () => {
    seedPorchSessionFixture("Porch Read Only").then(({ exerciseId }) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      // Journey 1: the feed renders — #2941's fixture-backed FeedRoute is
      // intentionally NOT login-state-aware yet (a future ticket swaps the
      // fixture source for a real per-viewer query), so a logged-out
      // reader sees the exact same populated feed anyone else does, with
      // NO login step and no redirect. Scoped to the Feed landmark
      // (`aria-label="Feed"`, `FeedPanel`) since "Priya Natarajan" (post-1's
      // author, `fixtures/posts.ts`) ALSO appears, hidden below `xl`, in the
      // persistent right rail's "People you may know" card
      // (`fixtures/rail.ts`) — @testing-library/dom's text matcher does no
      // CSS-visibility filtering, so an unscoped query would throw
      // "multiple elements" instead of a clean assertion.
      cy.findByRole("region", { name: "Feed" }).within(() => {
        cy.findByText("Priya Natarajan").should("be.visible");
      });

      // Journey 2: no acting profile -> no compose entry point at all.
      porchComposerTrigger().should("not.exist");

      // The account menu (topbar, "Account menu" trigger regardless of
      // signed-in state) is the log-in affordance's home.
      porchAccountMenuButton().should("be.visible").click();
      porchAccountMenu().within(() => {
        cy.findByText("You're not signed in").should("be.visible");
      });
      porchAccountLogInItem().should("be.visible");
      porchAccountLogOutItem().should("not.exist");
    });
  });

  it("clicking Log in opens the login modal in place — no navigation", () => {
    seedPorchSessionFixture("Porch Login Modal").then(({ exerciseId }) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      cy.location("pathname").then((before) => {
        openPorchLoginModal();

        // Journey 3: same document, same path — a modal, not a route.
        cy.location("pathname").should("eq", before);
        porchLoginDialog().within(() => {
          cy.findByLabelText("Handle").should("be.visible");
          cy.findByLabelText("Password").should("be.visible");
          cy.findByRole("button", { name: "Cancel" }).should("be.visible");
        });
      });
    });
  });

  it("an invalid credential shows a generic, non-enumerating error and leaves the modal open", () => {
    seedPorchSessionFixture("Porch Bad Creds").then(({ exerciseId, credential }) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();
      openPorchLoginModal();

      // Journey 6: a real handle with the WRONG password gets the exact
      // same opaque copy a nonexistent handle would (range-bff's
      // VerifyCredential returns one error for both) — this spec cannot
      // prove the two are byte-identical without a second run, but it
      // proves the message never claims "wrong password" specifically,
      // which is the enumeration leak #2869 rules out.
      submitPorchLogin(credential.handle, "definitely-not-the-password");

      porchLoginDialog().within(() => {
        cy.findByText("Invalid handle or password").should("be.visible");
      });
      // Still open — a failed attempt does not silently dismiss the modal.
      porchLoginDialog().should("be.visible");
      porchComposerTrigger().should("not.exist");
    });
  });

  it("a valid credential logs the character in, unlocks compose, and the account menu carries their identity", () => {
    seedPorchSessionFixture("Porch Good Creds", "Priya Natarajan").then(
      ({ exerciseId, credential }) => {
        visitRange(`/range/exercises/${exerciseId}/env`);
        porchToolbarButton().click();

        loginToPorch(credential.handle, credential.password);

        // Journey 4: modal closed onto the SAME feed view (see the first
        // test's note on scoping this to the Feed landmark to avoid the
        // right rail's duplicate "Priya Natarajan" row).
        porchLoginDialog().should("not.exist");
        cy.findByRole("region", { name: "Feed" }).within(() => {
          cy.findByText("Priya Natarajan").should("be.visible");
        });

        // The character's identity now appears in the chrome, and Log out
        // replaces Log in.
        porchAccountMenuButton().click();
        porchAccountMenu().within(() => {
          cy.findByText(credential.displayName).should("be.visible");
        });
        porchAccountLogOutItem().should("be.visible");
        porchAccountLogInItem().should("not.exist");
        cy.get("body").type("{esc}");

        // Compose unlocks.
        porchComposerTrigger().should("be.visible");
      },
    );
  });

  it("logging out returns to the logged-out-but-readable state without disturbing the shell session", () => {
    seedPorchSessionFixture("Porch Logout").then(({ exerciseId, credential }) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();
      loginToPorch(credential.handle, credential.password);
      porchComposerTrigger().should("be.visible");

      logOutOfPorch();

      // Journey 5: back to signed-out — no compose entry point, Log in
      // affordance restored, still on the SAME readable feed (not kicked
      // out anywhere; see the first test's note on scoping this to the
      // Feed landmark).
      cy.findByRole("region", { name: "Feed" }).within(() => {
        cy.findByText("Priya Natarajan").should("be.visible");
      });
      porchComposerTrigger().should("not.exist");
      porchAccountMenuButton().click();
      porchAccountMenu().within(() => {
        cy.findByText("You're not signed in").should("be.visible");
      });
      porchAccountLogInItem().should("be.visible");
      cy.get("body").type("{esc}");

      // The shell's OWN session is unaffected: leaving the env shell for a
      // shell-authenticated route lands on the real dashboard, not a
      // Keycloak redirect, and the shell's own (distinct) user menu is
      // reachable.
      visitRange("/range");
      cy.location("pathname").should("not.match", /\/login(\/|$)/);
      userMenuButton().should("be.visible");
    });
  });
});


