/**
 * Porch topbar build-out (issue #2945 — "Build the Porch topbar out: real
 * search, notifications and account menu").
 *
 * `PorchSearchStub` is gone: the topbar now carries a real, keyboard-operable
 * search field that submits to a results route, plus a notifications bell.
 * The account menu's own signed-in/out identity journeys (its whole reason
 * for existing per #2945 — "This is where #2869's login modal is triggered
 * from") are covered by porch-session.cy.ts, since they only make sense
 * alongside the login/logout flow; this spec covers the two OTHER pieces
 * #2945 adds: search -> results route, and notifications.
 *
 * Both are fixtures-only in this batch (no backend): #2945's own acceptance
 * criteria require "renders entirely from fixtures — a test fails if the
 * component issues a network call", so a spec asserting network-independent
 * fixture content (rather than seeded backend state) is the correct
 * behavior to pin here, not a gap. `PORCH_SEARCH_RESULTS_WITH_HITS.query`
 * ("riverside", `fixtures/search.ts`) is the one query PorchApp's fixture
 * lookup resolves to real hits; any other non-empty query falls to the
 * "no results" state, which is what most of this spec's queries land on.
 *
 * Actors: P7 (exercise STUDENT), matching porch-platform.cy.ts — no Porch
 * login (`porch_session`) is needed for any of this; search and
 * notifications ride the shell session alone.
 */
import { seedEnvExerciseAsP7, visitRange } from "./_helpers";
import {
  porchNotificationsButton,
  porchNotificationsMenu,
  porchSearchInput,
  porchToolbarButton,
} from "../../support/selectors";

describe("porch: topbar — search results route and notifications", () => {
  it("the search field is a real, non-readOnly control, keyboard-submittable to the results route", () => {
    seedEnvExerciseAsP7("Porch Topbar Search").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      porchSearchInput()
        .should("be.visible")
        .and("not.have.attr", "readonly");

      // Enter submits — no mouse click on a search button needed.
      porchSearchInput().type("riverside{enter}");

      cy.location("pathname").should("match", /\/search$/);
      cy.location("search").should("eq", "?q=riverside");

      // A query with real fixture hits renders both result sections.
      cy.findByRole("heading", { name: "Posts" }).should("be.visible");
      cy.findByRole("heading", { name: "People" }).should("be.visible");

      // Scoped to the People results section (`<section
      // aria-labelledby={peopleHeadingId}>`, an implicit ARIA "region"
      // named by its own heading) rather than a bare `findByText` — "Priya
      // Natarajan" is ALSO the Posts section's own post-1 author
      // (`fixtures/posts.ts`, reused as `PORCH_SEARCH_RESULTS_WITH_HITS`'s
      // first hit) and, hidden below `xl`, the persistent right rail's
      // "People you may know" suggestion row (`fixtures/rail.ts`'s
      // `PORCH_SUGGESTION_SOME_MUTUALS`) — @testing-library/dom's text
      // matcher does no CSS-visibility filtering, so an unscoped query
      // throws "multiple elements" rather than a normal assertion failure.
      cy.findByRole("region", { name: "People" }).within(() => {
        cy.findByText("Priya Natarajan").should("be.visible");
      });
    });
  });

  it("a query with no matching fixture renders the no-results state", () => {
    seedEnvExerciseAsP7("Porch Topbar No Results").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      porchSearchInput().type("zz-no-such-query-zz{enter}");

      cy.findByText("No results found").should("be.visible");
    });
  });

  it("the clear button resets the field", () => {
    seedEnvExerciseAsP7("Porch Topbar Clear").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      porchSearchInput().type("summit gala");
      cy.findByRole("button", { name: "Clear search" }).click();
      porchSearchInput().should("have.value", "");
    });
  });

  it("the notifications bell shows the unread badge and lists the fixture notifications", () => {
    seedEnvExerciseAsP7("Porch Topbar Notifications").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      // PorchApp.tsx wires the bell to `PORCH_NOTIFICATIONS_UNREAD`
      // (3 rows, 2 unread) unconditionally — not gated on `porch_session`,
      // and not the empty default `PorchNotificationsMenu` itself falls
      // back to when no `notifications` prop is supplied at all — so the
      // coherent state here is the populated badge + panel, not the empty
      // one.
      porchNotificationsButton()
        .should("be.visible")
        .within(() => {
          cy.findByText("2").should("be.visible");
        });

      porchNotificationsButton().click();
      porchNotificationsMenu().within(() => {
        cy.findByText("Priya Natarajan").should("be.visible");
        cy.findByText("Marcus Webb").should("be.visible");
        cy.findByText("The Riverside Book Club").should("be.visible");
      });
    });
  });
});



