/// <reference types="cypress" />
/**
 * Porch lane-local helpers (Epic #2821 — "Open Porch in the browser shell").
 * NOT steward-owned — this file is single-owner to the porch tranche, mirroring
 * range/_helpers.ts and kite/_helpers.ts's own doc comments. Shared foundation
 * (cy.login, cy.origin, personas, selectors) lives under support/ and stays
 * frozen; this module re-uses the range lane's exercise/membership seeding
 * surface directly rather than duplicating it, since Porch is a platform
 * SURFACE inside a Range exercise, not a separate product with its own
 * exercise/membership model.
 *
 * The one seam range/_helpers.ts has no equivalent for is platform_visibility
 * (#1478's per-exercise participant denylist, see
 * frontends/range-mfe/src/lib/platformVisibility.ts) — `setPlatformVisibility`
 * below fills that in with a direct PATCH, mirroring what
 * useSetPlatformVisibility.ts / PlatformsCard.tsx drive from the UI.
 */
import type { PersonaCreds } from "../../support/commands";
import {
  porchAccountLogInItem,
  porchAccountLogOutItem,
  porchAccountMenuButton,
  porchLoginDialog,
} from "../../support/selectors";
import {
  assignExerciseRole,
  bffPost,
  createActiveExercise,
  createCharacter,
  createFaction,
  uniq,
  visitRange,
} from "../range/_helpers";

export { assignExerciseRole, createActiveExercise, uniq, visitRange };

interface Envelope<T> {
  data?: T;
}

/** Unwrap the range-bff `{ data: ... }` envelope, tolerating a bare payload. */
function unwrap<T>(body: unknown): T {
  if (body && typeof body === "object" && "data" in body) {
    const env = body as Envelope<T>;
    if (env.data !== undefined) return env.data;
  }
  return body as T;
}

/**
 * The shared seeding chain both public seeders below are built on: log in as
 * P6 (creator/instructor), mint P7, create an ACTIVE exercise, enroll P7 as
 * STUDENT, run `whileInstructor` against that exercise while STILL on the P6
 * session, then switch to P7 and yield whatever `whileInstructor` produced.
 *
 * The P6-before-P7 ordering is the whole reason this is one helper: anything
 * needing RANGE_ADMIN on the exercise (credential minting) has to happen
 * before the session switches, and expressing that as a callback slot makes
 * it impossible for a caller to get the order wrong.
 */
function seedExerciseAsP7<T>(
  namePrefix: string,
  whileInstructor: (exerciseId: string) => Cypress.Chainable<T>,
): Cypress.Chainable<T> {
  cy.login("P6");
  return cy
    .task<PersonaCreds>("mintPersona", { persona: "P7" })
    .then((p7): Cypress.Chainable<T> =>
      createActiveExercise(uniq(namePrefix)).then((exerciseId): Cypress.Chainable<T> =>
        assignExerciseRole(exerciseId, p7.kcUserId, "student").then(
          (): Cypress.Chainable<T> =>
            whileInstructor(exerciseId).then(
              (result): Cypress.Chainable<T> =>
                cy.login("P7").then((): Cypress.Chainable<T> => cy.wrap<T>(result)),
            ),
        ),
      ),
    );
}

/**
 * Seed an active exercise, enroll P7 as STUDENT (the exercise-membership
 * "Participant" role), then switch the active cy.session to P7. Yields the
 * exercise id. Mirrors range/participant-env-shell.cy.ts's
 * seedEnvExerciseAsP7, generalized to a bare exercise id (this lane's specs
 * only need the id, not the exercise name).
 */
export function seedEnvExerciseAsP7(
  namePrefix = "Porch Env",
): Cypress.Chainable<string> {
  return seedExerciseAsP7(namePrefix, (exerciseId) => cy.wrap<string>(exerciseId));
}

/**
 * PATCH the exercise's `platform_visibility` denylist directly (#1478),
 * riding the shell proxy on whatever persona is CURRENTLY logged in — call
 * this while logged in as the exercise creator/instructor, since a
 * participant session has no write access to exercise settings.
 *
 * range-bff's PlatformVisibility field is a POINTER TO A MAP: a partial
 * `{ porch: false }` payload is a valid, deliberate partial denylist — every
 * OTHER key is simply absent, which `parsePlatformVisibility` /
 * `isPlatformEnabled` (platformVisibility.ts) both read as "enabled" by
 * default. This mirrors exactly what a single PlatformsCard toggle click
 * persists server-side EXCEPT that the real UI always sends the full
 * five-key map (useSetPlatformVisibility.ts) — sending only the key under
 * test is simpler here and observably equivalent, since an absent key and an
 * explicit `true` are the same enabled state.
 */
export function setPlatformVisibility(
  exerciseId: string,
  visibility: Readonly<Record<string, boolean>>,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "PATCH",
    url: `/api/v1/range/exercises/${exerciseId}`,
    body: { platform_visibility: visibility },
    headers: { "Content-Type": "application/json", Accept: "application/json" },
  });
}

// ---------------------------------------------------------------------------
// Porch acting identity (#2869) — a Porch login/logout is a DIFFERENT trust
// zone from the exercise-membership seam above: it authenticates a
// CHARACTER against range-bff's ParticipantCredentialService (the exact
// same service Kite/Commons verify against, per
// services/range-bff/internal/handlers/porch.go's Login doc comment), never
// the shell's own Keycloak session. There is no cookie-planting shortcut
// here (unlike cy.loginParticipantX/Commons) — the whole point of this
// slice's UI is that the credential is typed into PorchLoginModal in place,
// so these helpers drive the real form rather than short-circuiting it.
// ---------------------------------------------------------------------------

export interface PorchCredential {
  readonly characterId: string;
  readonly handle: string;
  readonly password: string;
  readonly displayName: string;
}

/**
 * Provision a human-playable (non-synthetic) character under `exerciseId`
 * and mint a Porch-loginnable credential for it via the SAME
 * `credentials:generate` route Kite/Commons use — range-bff's Porch Login
 * verifies against the identical ParticipantCredentialService, so one
 * credential authenticates any of the three surfaces. Call while logged in
 * as the exercise instructor/RANGE_ADMIN (P6 by default) — credential
 * minting requires that role on the exercise, mirroring
 * kite/_helpers.ts's createLoginnableCharacter.
 */
export function seedPorchCredential(
  exerciseId: string,
  displayName = "Jordan Ashworth",
): Cypress.Chainable<PorchCredential> {
  return createFaction(exerciseId, { name: uniq("Porch Faction") }).then((factionId) =>
    createCharacter(exerciseId, {
      faction_id: factionId,
      username: uniq("porchparticipant").toLowerCase().replace(/[^a-z0-9]/g, ""),
      display_name: displayName,
      is_synthetic: false,
    }).then((characterId) =>
      bffPost(`/api/v1/kite/exercises/${exerciseId}/credentials:generate`, {
        character_id: characterId,
      }).then((resp) => {
        const inner = unwrap<{ handle?: string; password?: string }>(resp.body);
        expect(inner.handle, "generated porch credential handle").to.be.a("string");
        expect(inner.password, "generated porch credential password").to.be.a("string");
        return {
          characterId,
          handle: inner.handle as string,
          password: inner.password as string,
          displayName,
        };
      }),
    ),
  );
}

/**
 * Open the Porch account menu and click "Log in" — asserts the login modal
 * (`PorchLoginModal`, "Log in to Porch") opens IN PLACE, never a navigation
 * (#2869 journey 3). Leaves the modal open for the caller to fill in.
 */
export function openPorchLoginModal(): void {
  porchAccountMenuButton().click();
  porchAccountLogInItem().click();
  porchLoginDialog().should("be.visible");
}

/**
 * Fill the open `PorchLoginModal`'s Handle/Password fields and submit.
 * Does not assert the outcome — callers assert either the modal closing
 * (success) or the inline error appearing (failure).
 */
export function submitPorchLogin(handle: string, password: string): void {
  porchLoginDialog().within(() => {
    cy.findByLabelText("Handle").clear().type(handle);
    cy.findByLabelText("Password").type(password, { log: false });
    cy.findByRole("button", { name: "Log in" }).click();
  });
}

/**
 * Full UI-driven Porch login: open the modal, fill the credential, submit,
 * and wait for the modal to close (success path only — see
 * `submitPorchLogin` for driving the invalid-credential path directly).
 */
export function loginToPorch(handle: string, password: string): void {
  openPorchLoginModal();
  submitPorchLogin(handle, password);
  porchLoginDialog().should("not.exist");
}

/** Open the Porch account menu and click "Log out" (#2869 journey 5). */
export function logOutOfPorch(): void {
  porchAccountMenuButton().click();
  porchAccountLogOutItem().click();
}

export interface PorchSessionFixture {
  readonly exerciseId: string;
  readonly credential: PorchCredential;
}

/**
 * `seedEnvExerciseAsP7` PLUS a Porch-loginnable credential on the same
 * exercise — for specs that need to actually log a character into Porch
 * (login/logout/composer journeys), not just read the anonymous feed.
 *
 * Ends on the P7 session, in the env shell's own exercise route — exactly
 * `seedEnvExerciseAsP7`'s contract — so a caller does not have to know about
 * the P6 detour in between.
 */
export function seedPorchSessionFixture(
  namePrefix = "Porch Login",
  displayName = "Jordan Ashworth",
): Cypress.Chainable<PorchSessionFixture> {
  return seedExerciseAsP7(namePrefix, (exerciseId) =>
    seedPorchCredential(exerciseId, displayName).then(
      (credential): PorchSessionFixture => ({ exerciseId, credential }),
    ),
  );
}


