 * "unavailable" state per the component's own state machine
 * (`PorchComposerModal.tsx`) — this spec asserts exactly that, and
 * deliberately does NOT attempt to submit a post or assert one was created.
 *
 * Every "unavailable" assertion below checks `aria-disabled`, never
 * `:disabled` — per this package's a11y convention (and this ticket's own
 * instructions), an inert control here stays a real, focusable element with
 * `aria-disabled="true"` + a paired `aria-describedby` hint, never native
 * `disabled` (which would drop it from the tab order).
 *
 * The composer trigger only exists once a Porch acting identity is present
 * (#2869's "no acting profile -> no compose entry point"), so every test
 * here logs a character in first via `_helpers.ts`'s `seedPorchSessionFixture`
 * / `loginToPorch` — the same real, UI-driven login porch-session.cy.ts
 * uses, not a shortcut.
 */
import { loginToPorch, seedPorchSessionFixture, visitRange } from "./_helpers";
import {
  porchComposerDialog,
  porchComposerTrigger,
  porchToolbarButton,
} from "../../support/selectors";

function openComposer(): void {
  porchComposerTrigger().click();
  porchComposerDialog().should("be.visible");
