  it("the inline trigger opens the composer modal, and Escape closes it exactly once and restores focus to the trigger", () => {
    openComposer();

    porchComposerDialog().within(() => {
      cy.findByRole("textbox", { name: "Post text" }).should("be.visible");
    });

    cy.get("body").type("{esc}");
    porchComposerDialog().should("not.exist");
    porchComposerTrigger().should("have.focus");
  });

  it("the audience selector defaults to Public and every option is a real, labelled radio", () => {
    openComposer();

    porchComposerDialog().within(() => {
      cy.findByRole("radio", { name: "Public" }).should(
        "have.attr",
        "aria-checked",
        "true",
      );
      cy.findByRole("radio", { name: "Friends" }).should(
        "have.attr",
        "aria-checked",
        "false",
