/**
 * Porch left + right rail build-out (issues #2946 — "Build the Porch left
 * rail out" — and #2947 — "Build the Porch right rail cards out").
 *
 * Both tickets are fixtures-only UI build-outs: nothing in either fetches,
 * so this spec pins the ONE reachable state today — no acting profile
 * (rail identity), and PorchApp.tsx's populated `PORCH_*_FEW` fixtures for
 * groups/suggestions/events (no real audience/mutual-friends backend yet:
 * friends/groups audience RPCs and #2830's mutual-friends slot are
 * separate, later-slice tickets) — rather than a state nothing in the
 * current tree can produce. Each card's own empty-state copy
 * (`porch_pymk_empty`/`porch_your_groups_empty`/`porch_events_rail_empty`)
 * exists in the component and is unit-tested there, but `PorchApp` never
 * wires `{ state: "empty" }` for any of the three, so it is unreachable
 * from here and this spec does not try to reach it.
 *
 * Left rail (#2946): the full `PorchNav` link list with a real active state
 * driven by the router (never a prop a route could forget to pass),
 * `ProfileCard`'s signed-out state (the existing `porch_profile_signed_out`
 * copy, "Not signed in" — distinct from the topbar account menu's own
 * "You're not signed in" copy; porch-session.cy.ts covers the account
 * menu's signed-in/out journeys, this spec covers the rail's), and
 * `YourGroupsCard` — `PorchApp.tsx` mounts it in the LEFT slot alongside
 * `ProfileCard`, despite belonging to #2947's card set.
 *
 * Right rail (#2947): `PeopleYouMayKnowCard` and `UpcomingEventsCard`, each
 * with its own row rendering (`PorchRailCard`, no shared component),
 * always mounted in `PorchLayout`'s persistent right slot — `hidden ...
 * xl:block`, Tailwind's 1280px breakpoint — regardless of which left-nav
 * destination is active.
 *
 * Actors: P7 (exercise STUDENT), matching porch-platform.cy.ts. No Porch
 * login is needed — the rail's signed-out defaults are exactly what a
 * participant with no acting profile sees.
 */
import { seedEnvExerciseAsP7, visitRange } from "./_helpers";
import { porchNav, porchToolbarButton } from "../../support/selectors";

describe("porch: left rail nav + right rail cards", () => {
  it("the left rail lists all five destinations with a router-driven active state", () => {
    seedEnvExerciseAsP7("Porch Rail Nav").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      porchNav().within(() => {
        for (const name of ["Feed", "Friends", "Groups", "Events", "Saved"]) {
          cy.findByRole("link", { name }).should("be.visible");
        }
        cy.findByRole("link", { name: "Feed" }).should(
          "have.attr",
          "aria-current",
          "page",
        );
      });

      porchNav().findByRole("link", { name: "Groups" }).click();
      porchNav().within(() => {
        cy.findByRole("link", { name: "Groups" }).should(
          "have.attr",
          "aria-current",
          "page",
        );
        cy.findByRole("link", { name: "Feed" }).should(
          "not.have.attr",
          "aria-current",
        );
      });
      cy.findByText("No groups yet").should("be.visible");
    });
  });

  it("the profile card shows the coherent signed-out state with no acting profile", () => {
    seedEnvExerciseAsP7("Porch Rail Profile").then((exerciseId) => {
      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      cy.findByText("Not signed in").should("be.visible");
    });
  });

  it("each right-rail card renders its own populated rows rather than one shared placeholder", () => {
    seedEnvExerciseAsP7("Porch Rail Right").then((exerciseId) => {
      // The right rail (People you may know, Upcoming events) is
      // `hidden ... xl:block` in PorchLayout.tsx — Tailwind's default `xl`
      // breakpoint, 1280px — well past Cypress's 1000x660 default viewport
      // (no override in cypress.config.ts, none here either), so widen the
      // viewport before asserting on it.
      cy.viewport(1280, 800);

      visitRange(`/range/exercises/${exerciseId}/env`);
      porchToolbarButton().click();

      // PorchApp.tsx wires GROUPS_STATE/SUGGESTIONS_STATE/EVENTS_STATE to
      // `{ state: "data" }` against the populated `PORCH_*_FEW` fixtures,
      // not `{ state: "empty" }` — so each card's real empty-state copy can
      // never render given the current wiring. Assert the actual populated
      // rendering instead: each card's own rows, scoped to its own
      // `<section aria-labelledby>` (an implicit ARIA "region", named by its
      // heading) since some row names (e.g. "Priya Natarajan") also appear
      // elsewhere on the page (the Feed's own post authors).
      cy.findByRole("region", { name: "People you may know" }).within(() => {
        cy.findByText("Elena Vasquez").should("be.visible");
        cy.findByText("Priya Natarajan").should("be.visible");
      });

      cy.findByRole("region", { name: "Your groups" }).within(() => {
        cy.findByText("Riverside Book Club").should("be.visible");
        cy.findByText("Trailhead Hikers").should("be.visible");
        cy.findByText("Neighborhood Watch").should("be.visible");
      });

      cy.findByRole("region", { name: "Upcoming events" }).within(() => {
        cy.findByText("Community Garden Cleanup").should("be.visible");
        cy.findByText("Trailhead Hikers: Sunset Loop").should("be.visible");
      });
    });
  });
});


